import XCTest
import SwiftData
@testable import itchPocket

/// Opens a V2 store generated by the pinned historical V2 source commit in CI.
/// The fixture is intentionally generated outside the current app target so
/// its SwiftData model identities come from the historical app module.
final class HistoricalV2StoreCompatibilityTests: XCTestCase {
    @MainActor
    func testHistoricalV2SourceStoreOpensAndMigratesWithoutDataLoss() throws {
        guard let fixturePath = ProcessInfo.processInfo.environment["ITCHPOCKET_HISTORICAL_V2_FIXTURE"],
              !fixturePath.isEmpty else {
            throw XCTSkip("CI must provide a V2 store generated by the pinned historical V2 source commit.")
        }

        let v2StoreURL = URL(fileURLWithPath: fixturePath)
        XCTAssertTrue(FileManager.default.fileExists(atPath: v2StoreURL.path))
        try SQLiteStoreIntegrityChecker.quickCheck(at: v2StoreURL)

        let root = v2StoreURL.deletingLastPathComponent().deletingLastPathComponent()
        defer { try? FileManager.default.removeItem(at: root) }

        try autoreleasepool {
            let schema = Schema(versionedSchema: ItchPocketSchemaV2Snapshot.self)
            let configuration = ModelConfiguration(
                "historical-v2-compatibility-read",
                schema: schema,
                url: v2StoreURL,
                allowsSave: false
            )
            let container = try ModelContainer(for: schema, configurations: [configuration])
            let context = container.mainContext

            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBDeveloper>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBGame>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBLibraryEntry>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBGameUpdate>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBCalendarEvent>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBSparkMetadata>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBTranslation>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBDiscoverySnapshot>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBUpdateWatch>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBLibraryCollection>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBLibraryStatusEvent>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBAppState>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBGameDetail>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBLibraryCollectionItem>()), 1)

            let game = try XCTUnwrap(context.fetch(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBGame>()).first)
            XCTAssertEqual(game.id, "historical-v2-game")
            XCTAssertEqual(game.descriptionText, "Historical V2 game description")
            XCTAssertEqual(game.galleryURLs, ["https://cdn.example/historical-v2.png"])

            let collection = try XCTUnwrap(context.fetch(FetchDescriptor<ItchPocketSchemaV2Snapshot.DBLibraryCollection>()).first)
            XCTAssertEqual(collection.gameIDs, ["historical-v2-game"])
        }

        let v3StoreURL = try V3StoreBootstrap.prepareStore(v2StoreURL: v2StoreURL)
        XCTAssertTrue(FileManager.default.fileExists(atPath: v2StoreURL.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: v3StoreURL.path))
        try SQLiteStoreIntegrityChecker.quickCheck(at: v2StoreURL)
        try SQLiteStoreIntegrityChecker.quickCheck(at: v3StoreURL)

        try autoreleasepool {
            let schema = Schema(versionedSchema: ItchPocketSchemaV3.self)
            let configuration = ModelConfiguration(
                "historical-v2-compatibility-v3",
                schema: schema,
                url: v3StoreURL
            )
            let container = try ModelContainer(for: schema, configurations: [configuration])
            let context = container.mainContext

            let game = try XCTUnwrap(context.fetch(FetchDescriptor<DBGame>()).first)
            XCTAssertEqual(game.id, "historical-v2-game")
            XCTAssertEqual(game.title, "Historical V2 Game")

            XCTAssertEqual(game.gameURL, "https://example.com/historical-v2-game")
            XCTAssertEqual(game.coverURL, "https://cdn.example/historical-v2-cover.png")
            XCTAssertEqual(game.engine, "Ren'Py")
            XCTAssertEqual(game.developerID, "historical-v2-developer")

            let developer = try XCTUnwrap(context.fetch(FetchDescriptor<DBDeveloper>()).first)
            XCTAssertEqual(developer.name, "Historical V2 Developer")
            XCTAssertEqual(developer.patreonURL, "https://patreon.com/historical-v2")

            let libraryEntry = try XCTUnwrap(context.fetch(FetchDescriptor<DBLibraryEntry>()).first)
            XCTAssertEqual(libraryEntry.status, "playing")
            XCTAssertTrue(libraryEntry.isFavorite)
            XCTAssertEqual(libraryEntry.notes, "historical V2 library entry")

            let update = try XCTUnwrap(context.fetch(FetchDescriptor<DBGameUpdate>()).first)
            XCTAssertEqual(update.id, "historical-v2-update")
            XCTAssertEqual(update.summary, "Historical update summary")
            XCTAssertTrue(update.isHistorical)

            let calendarEvent = try XCTUnwrap(context.fetch(FetchDescriptor<DBCalendarEvent>()).first)
            XCTAssertEqual(calendarEvent.sourceUpdateID, update.id)
            XCTAssertEqual(calendarEvent.gameTitleSnapshot, game.title)

            let spark = try XCTUnwrap(context.fetch(FetchDescriptor<DBSparkMetadata>()).first)
            XCTAssertEqual(spark.runtimeSeconds, 9876)
            XCTAssertEqual(spark.renpyVersion, "8.2.0")

            let translation = try XCTUnwrap(context.fetch(FetchDescriptor<DBTranslation>()).first)
            XCTAssertEqual(translation.translatedText, "你好")

            let discovery = try XCTUnwrap(context.fetch(FetchDescriptor<DBDiscoverySnapshot>()).first)
            XCTAssertEqual(discovery.payload, Data("historical-v2-discovery-payload".utf8))

            let watch = try XCTUnwrap(context.fetch(FetchDescriptor<DBUpdateWatch>()).first)
            XCTAssertEqual(watch.entityTag, "historical-v2-etag")
            XCTAssertTrue(watch.hasBaseline)

            let statusEvent = try XCTUnwrap(context.fetch(FetchDescriptor<DBLibraryStatusEvent>()).first)
            XCTAssertEqual(statusEvent.toStatus, "playing")

            let appState = try XCTUnwrap(context.fetch(FetchDescriptor<DBAppState>()).first)
            XCTAssertEqual(appState.stringValue, "preserved")
            XCTAssertEqual(appState.dataValue, Data("historical-v2-state".utf8))

            let collectionItem = try XCTUnwrap(context.fetch(FetchDescriptor<DBLibraryCollectionItem>()).first)
            XCTAssertEqual(collectionItem.collectionID, "historical-v2-collection")
            XCTAssertEqual(collectionItem.gameID, game.id)
            XCTAssertEqual(collectionItem.sortOrder, 0)

            let detail = try XCTUnwrap(context.fetch(FetchDescriptor<DBGameDetail>()).first)
            XCTAssertEqual(detail.gameID, game.id)
            XCTAssertEqual(detail.descriptionText, "Historical V2 game description")
            XCTAssertEqual(detail.galleryURLs, ["https://cdn.example/historical-v2.png"])

            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBDeveloper>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBLibraryEntry>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBGameUpdate>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBCalendarEvent>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBSparkMetadata>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBTranslation>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBDiscoverySnapshot>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBUpdateWatch>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBLibraryCollection>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBLibraryStatusEvent>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBAppState>()), 1)
            XCTAssertEqual(try context.fetchCount(FetchDescriptor<DBLibraryCollectionItem>()), 1)
        }
    }
}
